class Solution:
    def isOneEditDistance(self, s: str, t: str) -> bool:
        if len(s) > len(t):
            s, t = t, s
        if len(t) - len(s) > 1:
            return False
        for i, (a, b) in enumerate(zip(s, t)):
            if a != b:
                return s[i+1:] == t[i+1:] if len(s) == len(t) else s[i:] == t[i+1:]
        return len(t) == len(s) + 1

class Solution {
    public boolean isOneEditDistance(String s, String t) {
        if (s.length() > t.length()) { String x = s; s = t; t = x; }
        if (t.length() - s.length() > 1) return false;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != t.charAt(i))
                return s.length() == t.length() ? s.substring(i + 1).equals(t.substring(i + 1)) : s.substring(i).equals(t.substring(i + 1));
        }
        return t.length() == s.length() + 1;
    }
}

class Solution:
    def findPeakElement(self, nums: List[int]) -> int:
        left, right = 0, len(nums) - 1
        while left < right:
            mid = (left + right) // 2
            if nums[mid] > nums[mid + 1]:
                right = mid
            else:
                left = mid + 1
        return left

class Solution {
    public int findPeakElement(int[] nums) {
        int left = 0, right = nums.length - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] > nums[mid + 1]) right = mid; else left = mid + 1;
        }
        return left;
    }
}

class Solution:
    def findMissingRanges(self, nums: List[int], lower: int, upper: int) -> List[str]:
        out = []
        prev = lower - 1
        for x in nums + [upper + 1]:
            if x - prev >= 2:
                a, b = prev + 1, x - 1
                out.append(str(a) if a == b else f"{a}->{b}")
            prev = x
        return out

class Solution {
    public List<String> findMissingRanges(int[] nums, int lower, int upper) {
        List<String> out = new ArrayList<>();
        long prev = (long) lower - 1;
        for (int i = 0; i <= nums.length; i++) {
            long cur = i == nums.length ? (long) upper + 1 : nums[i];
            if (cur - prev >= 2) {
                long a = prev + 1, b = cur - 1;
                out.add(a == b ? Long.toString(a) : a + "->" + b);
            }
            prev = cur;
        }
        return out;
    }
}

class Solution:
    def maximumGap(self, nums: List[int]) -> int:
        if len(nums) < 2:
            return 0
        lo, hi = min(nums), max(nums)
        if lo == hi:
            return 0
        n = len(nums)
        size = max(1, (hi - lo + n - 2) // (n - 1))
        count = (hi - lo) // size + 1
        mins = [float('inf')] * count
        maxs = [float('-inf')] * count
        used = [False] * count
        for x in nums:
            i = (x - lo) // size
            mins[i] = min(mins[i], x); maxs[i] = max(maxs[i], x); used[i] = True
        ans, prev = 0, lo
        for i in range(count):
            if used[i]:
                ans = max(ans, int(mins[i] - prev)); prev = maxs[i]
        return ans

class Solution {
    public int maximumGap(int[] nums) {
        if (nums.length < 2) return 0;
        int lo = nums[0], hi = nums[0];
        for (int x : nums) { lo = Math.min(lo, x); hi = Math.max(hi, x); }
        if (lo == hi) return 0;
        int n = nums.length;
        long size = Math.max(1L, ((long) hi - lo + n - 2) / (n - 1));
        int count = (int) (((long) hi - lo) / size + 1);
        int[] mins = new int[count], maxs = new int[count]; boolean[] used = new boolean[count];
        Arrays.fill(mins, Integer.MAX_VALUE); Arrays.fill(maxs, Integer.MIN_VALUE);
        for (int x : nums) { int i = (int) (((long) x - lo) / size); mins[i] = Math.min(mins[i], x); maxs[i] = Math.max(maxs[i], x); used[i] = true; }
        int ans = 0, prev = lo;
        for (int i = 0; i < count; i++) if (used[i]) { ans = Math.max(ans, mins[i] - prev); prev = maxs[i]; }
        return ans;
    }
}

class Solution:
    def compareVersion(self, version1: str, version2: str) -> int:
        a, b = version1.split('.'), version2.split('.')
        for i in range(max(len(a), len(b))):
            x = int(a[i]) if i < len(a) else 0
            y = int(b[i]) if i < len(b) else 0
            if x != y:
                return 1 if x > y else -1
        return 0

class Solution {
    public int compareVersion(String version1, String version2) {
        String[] a = version1.split("\\."), b = version2.split("\\.");
        int n = Math.max(a.length, b.length);
        for (int i = 0; i < n; i++) {
            long x = i < a.length ? Long.parseLong(a[i]) : 0L;
            long y = i < b.length ? Long.parseLong(b[i]) : 0L;
            if (x != y) return x > y ? 1 : -1;
        }
        return 0;
    }
}

class Solution:
    def fractionToDecimal(self, numerator: int, denominator: int) -> str:
        if numerator == 0:
            return "0"
        sign = "-" if (numerator < 0) != (denominator < 0) else ""
        a, b = abs(numerator), abs(denominator)
        whole, rem = divmod(a, b)
        if rem == 0:
            return sign + str(whole)
        out, seen = [], {}
        while rem and rem not in seen:
            seen[rem] = len(out)
            rem *= 10
            digit, rem = divmod(rem, b)
            out.append(str(digit))
        if rem:
            i = seen[rem]
            out.insert(i, "("); out.append(")")
        return sign + str(whole) + "." + "".join(out)

class Solution {
    public String fractionToDecimal(int numerator, int denominator) {
        if (numerator == 0) return "0";
        String sign = ((numerator < 0) ^ (denominator < 0)) ? "-" : "";
        long a = Math.abs((long) numerator), b = Math.abs((long) denominator);
        StringBuilder out = new StringBuilder(sign).append(a / b);
        long rem = a % b;
        if (rem == 0) return out.toString();
        out.append('.'); Map<Long, Integer> seen = new HashMap<>();
        while (rem != 0 && !seen.containsKey(rem)) {
            seen.put(rem, out.length()); rem *= 10; out.append(rem / b); rem %= b;
        }
        if (rem != 0) out.insert(seen.get(rem).intValue(), "(").append(')');
        return out.toString();
    }
}

class Solution:
    def twoSum(self, numbers: List[int], target: int) -> List[int]:
        left, right = 0, len(numbers) - 1
        while left < right:
            total = numbers[left] + numbers[right]
            if total == target:
                return [left + 1, right + 1]
            if total < target:
                left += 1
            else:
                right -= 1
        return []

class Solution {
    public int[] twoSum(int[] numbers, int target) {
        int l = 0, r = numbers.length - 1;
        while (l < r) {
            int sum = numbers[l] + numbers[r];
            if (sum == target) return new int[]{l + 1, r + 1};
            if (sum < target) l++; else r--;
        }
        return new int[0];
    }
}

class Solution:
    def convertToTitle(self, columnNumber: int) -> str:
        out = []
        while columnNumber:
            columnNumber -= 1
            out.append(chr(ord('A') + columnNumber % 26))
            columnNumber //= 26
        return ''.join(reversed(out))

class Solution {
    public String convertToTitle(int columnNumber) {
        StringBuilder out = new StringBuilder();
        while (columnNumber > 0) {
            columnNumber--;
            out.append((char) ('A' + columnNumber % 26));
            columnNumber /= 26;
        }
        return out.reverse().toString();
    }
}

class Solution:
    def majorityElement(self, nums: List[int]) -> int:
        candidate, count = 0, 0
        for x in nums:
            if count == 0:
                candidate = x
            count += 1 if x == candidate else -1
        return candidate

class Solution {
    public int majorityElement(int[] nums) {
        int candidate = 0, count = 0;
        for (int x : nums) {
            if (count == 0) candidate = x;
            count += x == candidate ? 1 : -1;
        }
        return candidate;
    }
}

class TwoSum:
    def __init__(self):
        self.counts = {}

    def add(self, number: int) -> None:
        self.counts[number] = self.counts.get(number, 0) + 1

    def find(self, value: int) -> bool:
        for x, count in self.counts.items():
            y = value - x
            if y in self.counts and (y != x or count > 1):
                return True
        return False

class TwoSum {
    private final Map<Integer, Integer> counts = new HashMap<>();
    public void add(int number) { counts.merge(number, 1, Integer::sum); }
    public boolean find(int value) {
        for (Map.Entry<Integer, Integer> e : counts.entrySet()) {
            int x = e.getKey(), y = value - x;
            Integer countY = counts.get(y);
            if (countY != null && (x != y || e.getValue() > 1)) return true;
        }
        return false;
    }
}
